create table public.qualification_policies(id uuid primary key default gen_random_uuid(),policy_version text not null unique,configuration jsonb not null,created_at timestamptz not null default now());
create table public.qualification_evaluations(id uuid primary key default gen_random_uuid(),candidate_id uuid not null references public.jackpot_candidates(id),candidate_revision integer not null,policy_version text not null references public.qualification_policies(policy_version),information_cutoff_at timestamptz not null,evaluated_at timestamptz not null,current_state text not null,eligible_next_state text not null,requirements_passed integer not null,requirements_failed integer not null,requirements_unknown integer not null,final_decision text not null check(final_decision in('QUALIFIED','WATCH','REJECTED')),decision_reason text not null check(decision_reason in('PASS','TRUE_NEGATIVE','DATA_BLOCKED')),input_hash text not null unique,created_at timestamptz not null default now(),unique(candidate_id,candidate_revision,policy_version));
create table public.qualification_requirements(id uuid primary key default gen_random_uuid(),evaluation_id uuid not null references public.qualification_evaluations(id),requirement_key text not null,status text not null check(status in('PASS','FAIL','UNKNOWN','NOT_APPLICABLE')),blocker_code text,observed_value jsonb,required_value jsonb,evidence_refs jsonb not null default'[]',source text,data_quality numeric,information_cutoff_at timestamptz not null,created_at timestamptz not null default now(),unique(evaluation_id,requirement_key));
create table public.qualification_aggregate_snapshots(id uuid primary key default gen_random_uuid(),policy_version text not null,funnel jsonb not null,blocker_frequency jsonb not null,unknown_frequency jsonb not null,coverage_gaps jsonb not null,policy_strictness jsonb not null,information_cutoff_at timestamptz not null,input_hash text not null unique,created_at timestamptz not null default now());
create or replace function public.prevent_qualification_history_mutation()returns trigger language plpgsql as $$begin raise exception'Qualification history is immutable';end$$;
create trigger qualification_policies_immutable before update or delete on public.qualification_policies for each row execute function public.prevent_qualification_history_mutation();
create trigger qualification_evaluations_immutable before update or delete on public.qualification_evaluations for each row execute function public.prevent_qualification_history_mutation();
create trigger qualification_requirements_immutable before update or delete on public.qualification_requirements for each row execute function public.prevent_qualification_history_mutation();
create trigger qualification_aggregates_immutable before update or delete on public.qualification_aggregate_snapshots for each row execute function public.prevent_qualification_history_mutation();
alter table public.qualification_policies enable row level security;alter table public.qualification_evaluations enable row level security;alter table public.qualification_requirements enable row level security;alter table public.qualification_aggregate_snapshots enable row level security;
create policy "public read qualification policies" on public.qualification_policies for select using(true);create policy "public read qualification evaluations" on public.qualification_evaluations for select using(true);create policy "public read qualification requirements" on public.qualification_requirements for select using(true);create policy "public read qualification aggregates" on public.qualification_aggregate_snapshots for select using(true);
grant select on public.qualification_policies,public.qualification_evaluations,public.qualification_requirements,public.qualification_aggregate_snapshots to anon,authenticated;grant all on public.qualification_policies,public.qualification_evaluations,public.qualification_requirements,public.qualification_aggregate_snapshots to service_role;
alter table public.ingestion_runs drop constraint if exists ingestion_runs_job_kind_check;alter table public.ingestion_runs add constraint ingestion_runs_job_kind_check check(job_kind in('stock_quotes','wallet_transactions','wallet_discovery','crypto_market','wallet_pnl','wallet_evidence','fast_flow','wallet_clustering','jackpot_collector','jackpot_outcomes','market_events','paper_eligibility','paper_execution','paper_exits','paper_valuation','performance','fx','qualification'));
